<script setup lang="ts">
import { Head, Link, useForm } from '@inertiajs/vue3'; import { Button } from '@/components/ui/button'; import { Input } from '@/components/ui/input'; import { Label } from '@/components/ui/label'; type Type={value:string;label:string;consumption_unit:string}; const props=defineProps<{target:{year:number;month:number;label:string};previousFlourQuantity:string;utilityTypes:Type[];previousMonth:{from:string;to:string}}>(); const form=useForm({year:props.target.year,month:props.target.month,utilities:props.utilityTypes.map(type=>({utility_type:type.value,billed_from:props.previousMonth.from,billed_to:props.previousMonth.to,paid_at:props.previousMonth.to,total_amount:0,business_percentage:50,household_percentage:50,physical_consumption:null as number|null,reference:'',manual_rate:Number(props.previousFlourQuantity)>0?null as number|null:0,override_reason:''}))}); const money=(value:number)=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(value||0); const typeFor=(value:string)=>props.utilityTypes.find(type=>type.value===value)!; const businessAmount=(line:any)=>Math.round(Number(line.total_amount||0)*Number(line.business_percentage||0)/100); const suggested=(line:any)=>Number(props.previousFlourQuantity)>0?Math.round(businessAmount(line)/Number(props.previousFlourQuantity)):null; const setBusiness=(line:any)=>line.household_percentage=Math.max(0,100-Number(line.business_percentage||0));
</script>
<template><Head title="Abrir periodo de costos" /><main class="flex flex-1 flex-col gap-5 p-4 md:p-6"><header><p class="text-sm text-muted-foreground">Periodo de producción</p><h1 class="text-2xl font-semibold">{{ target.label }}</h1><p class="text-sm text-muted-foreground">Base anterior: {{ previousFlourQuantity }} kg de harina procesada.</p></header><form class="grid gap-5" @submit.prevent="form.post('/cost-periods')"><article v-for="(line,index) in form.utilities" :key="line.utility_type" class="grid gap-4 rounded-xl border bg-card p-5"><div><h2 class="font-semibold">{{ typeFor(line.utility_type).label }}</h2><p class="text-xs text-muted-foreground">Factura pagada del periodo anterior.</p></div><div class="grid gap-4 md:grid-cols-3"><div class="grid gap-2"><Label>Facturado desde</Label><Input v-model="line.billed_from" type="date" /></div><div class="grid gap-2"><Label>Facturado hasta</Label><Input v-model="line.billed_to" type="date" /></div><div class="grid gap-2"><Label>Fecha de pago</Label><Input v-model="line.paid_at" type="date" /></div><div class="grid gap-2"><Label>Valor total COP</Label><Input v-model.number="line.total_amount" type="number" min="0" /></div><div class="grid gap-2"><Label>Consumo {{ typeFor(line.utility_type).consumption_unit }} (opcional)</Label><Input v-model.number="line.physical_consumption" type="number" min="0" step="0.000001" /></div><div class="grid gap-2"><Label>Referencia</Label><Input v-model="line.reference" /></div><div class="grid gap-2"><Label>Negocio %</Label><Input v-model.number="line.business_percentage" type="number" min="0" max="100" step="0.0001" @input="setBusiness(line)" /></div><div class="grid gap-2"><Label>Hogar %</Label><Input v-model.number="line.household_percentage" type="number" min="0" max="100" step="0.0001" /></div><div class="rounded-lg bg-muted/40 p-3 text-sm"><p>Negocio: <strong>{{ money(businessAmount(line)) }}</strong></p><p>Hogar: <strong>{{ money(Number(line.total_amount)-businessAmount(line)) }}</strong></p></div></div><div class="grid gap-4 border-t pt-4 md:grid-cols-3"><div class="rounded-lg bg-muted/40 p-3 text-sm"><p class="text-xs text-muted-foreground">Tarifa sugerida</p><strong>{{ suggested(line)===null?'Sin historial':`${money(suggested(line)!)}/kg` }}</strong></div><div class="grid gap-2"><Label>Tarifa manual COP/kg {{ suggested(line)===null?'(obligatoria)':'(opcional)' }}</Label><Input v-model.number="line.manual_rate" type="number" min="0" /></div><div class="grid gap-2"><Label>Motivo de tarifa manual</Label><Input v-model="line.override_reason" :required="line.manual_rate!==null&&line.manual_rate!==suggested(line)" /></div></div><p v-if="form.errors[`utilities.${index}.business_percentage`]" class="text-sm text-destructive">{{ form.errors[`utilities.${index}.business_percentage`] }}</p></article><p v-if="Object.keys(form.errors).length" class="text-sm text-destructive">{{ Object.values(form.errors)[0] }}</p><div class="flex justify-end gap-2"><Button variant="outline" as-child><Link href="/cost-periods">Cancelar</Link></Button><Button type="submit" :disabled="form.processing">Abrir periodo y fijar tarifas</Button></div></form></main></template>
